					fLookups = GetNewLookups();
				}

				return fLookups;
			}
		}

		protected virtual AUAddInfoLookups GetNewLookups()
		{
			return new AUAddInfoLookups(this);
		}

		AUAddInfoLookups fLookups;

		#endregion

		#region Validation

		protected override void RunPreSaveValidationCore()
		{
			Validation.ValidateAll();
			base.RunPreSaveValidationCore(); // call RunPreSaveValidationCore() on all children then fire OnNotificationsChanged()
		}

		public AUAddInfoValidation Validation
		{
			get { return GetNewValidation(); }
		}

		protected virtual AUAddInfoValidation GetNewValidation()
		{
			return new AUAddInfoValidation(this);
		}

		#endregion
	}
}
